#[verus]
pub fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // Precondition: indices must not be empty and choices must have at least one row
    // and each row must have the same length as indices.
    assert!(!indices.is_empty());
    assert!(!choices.is_empty());
    assert!(choices.iter().all(|row| row.len() == indices.len()));
    assert!(indices.iter().all(|&index| index < choices.len() as u8));

    // The length of the result will be the same as the length of indices
    let mut result: Vec<f64> = vec![0.0; indices.len()];

    // Loop through each index and fill the result array
    for i in 0..indices.len() {
        // Invariant: 0 <= i <= indices.len()
        // Ensure that we are accessing valid rows and columns
        let row_index = indices[i] as usize;
        let col_index = i;

        // Ensure that the row index is valid
        assert!(row_index < choices.len());
        // Ensure that the column index is valid
        assert!(col_index < choices[row_index].len());

        // Assign the value from the matrix to the result
        result[i] = choices[row_index][col_index];
    }

    // Postcondition: The result length must be equal to the length of indices
    assert!(result.len() == indices.len());

    result
}